const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({house:'<path d="m3 10 9-7 9 7M5 9v12h14V9M9 21v-8h6v8"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6Z"/>',grid:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',leaf:'<path d="M20 3c0 12-5 17-11 14-6-3-3-11 11-14ZM4 21l11-12"/>',check:'<path d="m5 12 4 4 10-10"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',compare:'<path d="M8 3v18M16 3v18M3 8h10m-3-3 3 3-3 3M11 16h10m-3-3 3 3-3 3"/>',file:'<path d="M6 3h9l4 4v14H6ZM14 3v5h5M9 12h7M9 16h7"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',trash:'<path d="M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7"/>'})[name]||'<circle cx="12" cy="12" r="8"/>'}</svg>`;
let houses=[],page='home',draft=null,step=0,fi=0,selection=null,tool='select',currentId=null,planId=null,compareIds=new Set(),reportFilter='all',overlay=true,toastTimer;
let dirty=false;let serviceStatus={maps:false,vision:false};
let sketch=[];

const active=()=>houses.find(h=>h.id===currentId);
const floor=()=>draft?.floors[fi];
const labelKind={good:'值得保留',attention:'留意与优化',unknown:'待核实',fact:'空间方位'};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function touch(){if(draft){syncAttributes(draft);draft.revision++;if(page==='editor')draft.summaryConfirmed=false;dirty=true;}}
function setPage(p){page=p;render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});}
async function persist(h){if(page==='editor'&&draft?.id===h.id)h.intakeStep=step;syncAttributes(h);await putHouse(h);const i=houses.findIndex(x=>x.id===h.id);if(i>=0)houses[i]=structuredClone(h);else houses.push(structuredClone(h));}
function modal(title,body,buttons){const d=$('#modal');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" data-dialog-close aria-label="关闭">${icon('close')}</button></div>${body}<div class="dialog-actions">${buttons}</div>`;d.showModal();$('[data-dialog-close]').onclick=()=>d.close();d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());}
function confirmAction(title,body,run){modal(title,`<p>${body}</p>`,`<button class="btn ghost" data-close>取消</button><button class="btn primary" id="confirm-action">确认</button>`);$('#confirm-action').onclick=async()=>{try{await run();$('#modal').close();}catch(e){toast(e.message);}};}
const brand=`<a class="brand" href="#home" aria-label="观宅首页"><img src="./assets/brand.svg" alt="" width="42" height="42"><span>观宅<small>GUAN ZHAI</small></span></a>`;
function header(){return `<header class="header"><div class="header-inner">${brand}<nav aria-label="主导航"><a href="#home" ${page==='home'?'aria-current="page"':''}>首页</a><a href="#archive" ${page==='archive'?'aria-current="page"':''}>我的宅档</a><a href="#plans" ${page==='plans'?'aria-current="page"':''}>我的方案</a><button class="nav-example" data-action="demo">示例报告</button>${page==='home'?'<a class="nav-zhixing" href="https://zhixng.cn/app.html?from=guanzhai" target="_blank" rel="noopener noreferrer">知星排盘 ↗</a>':''}</nav><button class="btn header-cta" data-new="home">${icon('plus',16)} 新建宅档</button></div></header>`;}
function footer(){return `<footer class="footer">${page!=='editor'?'<button class="footer-back" data-action="go-back">← 返回上一级</button>':''}<span>观宅 <i>·</i> 观一宅格局，寻一处安居</span><div><button data-action="privacy">${icon('lock',13)} 宅档保存在本机</button><button data-action="about">关于分析</button><span>体验版 0.7</span></div></footer>`;}
function render(){const drawingOpen=page==='report'&&$('.report-drawing')?.open;const body=({home:home,editor:editor,archive:archive,report:report,compare:compare,planner:planner,plan:planView,plans:plans})[page]||home;document.body.classList.toggle('is-intake',page==='editor');document.body.classList.toggle('is-home',page==='home');$('#app').innerHTML=header()+`<main id="main" tabindex="-1">${body()}</main>`+footer();bind();if(drawingOpen&&$('.report-drawing'))$('.report-drawing').open=true;}
function zhixingEntry(){return `<aside class="zhixing-entry" aria-label="知星排盘与个人解读"><div><span class="source-tag">知星 × 观宅</span><h2>先读懂自己，再看适合的家</h2><p>知星排盘与个人解读；观宅结合户主八字，逐房间分析人宅关系。</p></div><a class="btn outline" href="https://zhixng.cn/app.html?from=guanzhai" target="_blank" rel="noopener noreferrer">去知星排盘 ↗</a><small>两个产品独立保存资料，跳转不传递出生信息。</small></aside>`;}
function home(){return `<section class="mobile-home"><div class="home-title"><span>东方居住智慧</span><h1>观一宅格局<br>寻一处<span>安居</span></h1></div><figure class="architecture-hero"><img src="./assets/hero-architecture-luopan-v2.png" alt="住宅建筑剖视与罗盘" width="1254" height="1254" fetchpriority="high"></figure><div class="home-entry-pair"><button class="home-entry" data-new="home"><b>分析我的家</b><span>看懂现有格局，找到改善方法</span>${icon('arrow')}</button><button class="home-entry" data-new="compare"><b>比较候选房</b><span>并排比较，选更适合的一宅</span>${icon('compare')}</button></div><p class="home-local-note">上传户型图 · 标明八方位 · 宅档保存在本机</p></section>`;}

function field(label,html,full=false){return `<label class="field ${full?'full':''}"><span>${label}</span>${html}</label>`;}
function input(key,value,extra=''){return `<input data-field="${key}" value="${esc(value)}" ${extra}>`;}
function options(map,value){return Object.entries(map).map(([k,v])=>`<option value="${k}" ${k===value?'selected':''}>${esc(v)}</option>`).join('');}
function progress(){return `<div class="stepper">${['上传户型','确认方位与图面','居住需求','确认生成'].map((s,i)=>`<button data-step="${i}" ${i>step?'disabled':''} class="${i===step?'active':''}"><b>${i<step?icon('check',14):`0${i+1}`}</b><span>${s}</span></button>`).join('')}</div>`;}
function editor(){return draft?intake(draft,step,fi,{canvas,floorTabs,selection,tool,sketch,services:serviceStatus}):'';}
function uploadStep(){return `<div class="upload-layout"><div class="panel"><div class="panel-title"><span class="tiny-index">先确认三件事</span><h2>从房屋现状，确定调整范围</h2></div><div class="setup-questions">${field('01 · 房子的类型',`<select data-field="type">${options({apartment:'商品房',self:'自建房',villa:'别墅 / 多层住宅'},draft.type)}</select>`,true)}<div class="setup-question"><span>02 · 毛坯还是精装？</span><div class="finish-options">${[['shell','毛坯'],['furnished','精装']].map(([k,v])=>`<button data-finish="${k}" class="${draft.finish===k?'selected':''}" aria-pressed="${draft.finish===k}">${v}</button>`).join('')}</div></div><div class="setup-question"><span>03 · 能接受怎样的方案？</span>${tierPicker()}</div></div><details class="optional-house"><summary>宅档名称与面积（选填）</summary><div class="form-grid">${field('宅档名称',input('name',draft.name,'placeholder="留空自动命名" maxlength="40"'))}${field('套内面积',input('area',draft.area,'type="number" min="1" max="5000" placeholder="平方米"'))}</div></details><div class="upload-zone" id="drop-zone"><div class="upload-icon">${icon('upload',30)}</div><h3>上传户型图</h3><p>拖入图片，或点击选择文件</p><label class="btn outline file-label">选择户型图<input id="file-input" type="file" accept="image/png,image/jpeg,image/webp" multiple></label><small>JPG / PNG / WEBP · 单张不超过 10 MB<br>多层住宅可逐层上传</small></div>${draft.floors.length?`<div class="file-list">${draft.floors.map((f,i)=>`<div><img src="${f.image}" alt="${esc(f.name)}"><span>${esc(f.name)}<small>${f.width} × ${f.height}</small></span><button class="icon-btn" data-remove-floor="${i}" aria-label="删除${esc(f.name)}">${icon('trash',17)}</button></div>`).join('')}</div>`:''}</div><aside class="upload-aside"><div class="example-frame"><img src="./assets/sample-plan.svg" alt="户型示例"><span>户型示例</span></div><h3>图越清楚，操作越直接。</h3><ul class="quiet-list"><li>选择家具后，标识直接出现在左上角。</li><li>拖动圆点缩放房间，也可以沿边勾线。</li><li>下一步确认八个方位。</li></ul><button class="text-link" data-action="sample-upload">用示例户型体验 ${icon('arrow',15)}</button></aside></div>`;}

function compass(north=0){return `<div class="compass" style="--north:${north}deg"><div class="compass-ring">${['北','东北','东','东南','南','西南','西','西北'].map((t,i)=>`<span class="eight-label" style="left:${50+42*Math.sin(i*Math.PI/4)}%;top:${50-42*Math.cos(i*Math.PI/4)}%">${t}</span>`).join('')}<div class="needle"></div></div><i></i></div>`;}

function floorTabs(fs,idx,edit=false){return `<div class="floor-tabs">${fs.map((f,i)=>`<button class="${i===idx?'active':''}" data-floor="${i}" data-floor-context="${edit?'editor':'view'}">${esc(f.name)}${edit?` <small>${f.confirmed&&f.directionConfirmed?'✓':'待确认'}</small>`:''}</button>`).join('')}</div>`;}
function canvas(f,{editable=false,show=true,plan=null,after=false}={}){
 const stage=page==='editor'?step:-1,filteredRooms=stage===8?f.rooms.filter(r=>r.id===selection):stage===9?[]:f.rooms;const visibleRooms=stage>=0&&stage<8?[]:filteredRooms;const marks=structuredClone(stage===8?[]:stage===9?f.markers.filter(m=>m.id===selection):f.markers);if(plan&&after)for(const move of plan.moves.filter(m=>m.floorId===f.id)){const m=marks.find(m=>m.id===move.id);if(m)Object.assign(m,move.to);}
 const selected=f.rooms.find(r=>r.id===selection);
 const handles=(r,id)=>[['nw',r.x,r.y],['ne',r.x+r.w,r.y],['sw',r.x,r.y+r.h],['se',r.x+r.w,r.y+r.h]].map(([edge,x,y])=>`<button class="resize-handle ${edge}" data-handle="${edge}" data-region="${id}" style="left:${x*100}%;top:${y*100}%" aria-label="拖动${edge}角缩放"></button>`).join('');
 return `<div class="plan-canvas ${editable?'editable':''}" id="${editable?'edit-canvas':after?'after-canvas':'view-canvas'}" style="aspect-ratio:${f.width}/${f.height}" data-tool="${tool}"><img draggable="false" src="${f.image}" alt="${esc(f.name)}户型图"><div class="plot-boundary ${editable&&tool==='bounds'?'editing-boundary':''} ${show?'':'hidden'}" ${editable&&tool==='bounds'?'data-select="$bounds"':''} style="left:${f.bounds.x*100}%;top:${f.bounds.y*100}%;width:${f.bounds.w*100}%;height:${f.bounds.h*100}%"></div>${f.boundary&&(stage<0||stage===5||stage===10)?`<svg class="boundary-red" viewBox="0 0 1000 1000" preserveAspectRatio="none"><polygon points="${f.boundary.map(p=>`${p.x*1000},${p.y*1000}`).join(' ')}"/></svg>`:''}${show?visibleRooms.map(r=>{const anchor=roomAnchor(r);return `<button class="room-region ${selection===r.id?'selected':''} ${r.locked?'locked':''} ${r.points?'polygon-room':''}" data-select="${r.id}" style="left:${r.x*100}%;top:${r.y*100}%;width:${r.w*100}%;height:${r.h*100}%;${r.points?`clip-path:polygon(${r.points.map(p=>`${(p.x-r.x)/r.w*100}% ${(p.y-r.y)/r.h*100}%`).join(',')})`:''}" aria-label="${esc(r.name)}标注区域"><span style="position:absolute;left:${(anchor.x-r.x)/r.w*100}%;top:${(anchor.y-r.y)/r.h*100}%;transform:translate(-50%,-50%)">${r.locked?'⌑ ':''}${esc(r.name)}${r.measurements?`<small class="room-measure">${esc(r.measurements.width||'未知')} × ${esc(r.measurements.depth||'未知')} 米</small>`:''}</span></button>${r.points?`<svg class="room-outline" viewBox="0 0 1000 1000" preserveAspectRatio="none"><polygon points="${r.points.map(p=>`${p.x*1000},${p.y*1000}`).join(' ')}" class="${selection===r.id?'selected':''}"/></svg>`:''}`;}).join(''):''}${show&&stage<0?footprints(f,marks):''}${editable&&page!=='editor'?recognitionOverlay(f)+calibrationOverlay(f):''}${show?marks.map(m=>`<button class="furniture ${selection===m.id?'selected':''}" data-select="${m.id}" data-marker-type="${m.type}" style="left:${m.x*100}%;top:${m.y*100}%;--symbol-scale:${m.uiScale||1}" aria-label="${esc(MARKERS[m.type]||'物件')}位置">${symbol(m.type)}</button>`).join(''):''}${editable&&show&&selected?handles(selected,selected.id)+(selected.points?selected.points.map((p,i)=>`<button class="poly-vertex" data-vertex="${i}" data-region="${selected.id}" style="left:${p.x*100}%;top:${p.y*100}%" aria-label="轮廓顶点${i+1}"></button>`).join(''):''):''}${editable&&tool==='bounds'?handles(f.bounds,'$bounds'):''}${editable&&sketch.length?`<svg class="sketch-lines" viewBox="0 0 1000 1000" preserveAspectRatio="none"><polyline points="${sketch.map(p=>`${p.x*1000},${p.y*1000}`).join(' ')}"/>${sketch.map(p=>`<circle cx="${p.x*1000}" cy="${p.y*1000}" r="6"/>`).join('')}</svg>`:''}${after&&plan?`<svg class="move-lines" viewBox="0 0 1000 1000" preserveAspectRatio="none"><defs><marker id="arrow-tip" markerWidth="7" markerHeight="7" refX="5" refY="3" orient="auto"><path d="M0 0 6 3 0 6" fill="none" stroke="#996635" stroke-width="1.5"/></marker></defs>${plan.moves.filter(m=>m.floorId===f.id).map(m=>`<path d="M${m.from.x*1000},${m.from.y*1000} L${m.to.x*1000},${m.to.y*1000}" marker-end="url(#arrow-tip)"/>`).join('')}${plan.partitions.filter(p=>p.floorId===f.id).map(p=>`<path class="partition-line" d="M${p.x*1000} ${p.y*1000}v${p.h*1000}"/>`).join('')}</svg>`:''}${stage<0||stage===7||stage===10?`<div class="map-compass">${compass(f.north)}</div>`:''}</div>`;
}

function markStep(){const f=floor();if(!f)return '<p>请先上传户型图。</p>';const obj=f.rooms.find(r=>r.id===selection)||f.markers.find(m=>m.id===selection);return `<div class="annotation-layout revised"><div class="drawing-panel">${floorTabs(draft.floors,fi,true)}<div class="drawing-toolbar"><button data-tool="select" class="${tool==='select'?'active':''}">选择 / 移动</button><button data-action="add-room">${icon('plus',14)} 矩形房间</button><button data-tool="polygon" class="${tool==='polygon'?'active':''}">勾线房间</button><button data-tool="bounds" class="${tool==='bounds'?'active':''}">房屋范围</button><button data-action="toggle-overlay" class="icon-btn" aria-label="切换标注显示">${icon('grid',17)}</button></div><div class="object-palette"><label for="marker-tool">添加家具 / 设施</label><select id="marker-tool"><option value="">选择后出现在左上角</option>${[...new Set(Object.values(CATALOG).map(c=>c.group))].map(g=>`<optgroup label="${g}">${Object.entries(CATALOG).filter(([k,c])=>c.group===g).map(([k,c])=>`<option value="${k}">${c.name}</option>`).join('')}</optgroup>`).join('')}</select><div class="quick-markers">${['door','window','bed','desk','sofa','wardrobe','sink','plant'].map(k=>`<button data-add-marker="${k}">${CATALOG[k].name}</button>`).join('')}</div></div>${canvas(f,{editable:true,show:overlay})}<div class="on-canvas-actions">${tool==='scale'?`<span>点击实测线段的两个端点 · ${sketch.length}/2</span><button data-action="cancel-polygon">取消标定</button>`:tool==='polygon'?`<span>依次点击房间拐角 · ${sketch.length} 个点</span><button data-action="undo-point" ${!sketch.length?'disabled':''}>撤回一点</button><button data-action="close-polygon" ${sketch.length<3?'disabled':''}>闭合轮廓</button><button data-action="cancel-polygon">取消</button>`:obj?`<span>${esc(obj.name||MARKERS[obj.type])}</span>${'w'in obj?'<button data-action="rename-room">命名 / 用途</button>':'<button data-action="marker-dimensions">尺寸 / 朝向</button>'}<button data-action="toggle-lock">${obj.locked?'解除保留':'保留不动'}</button><button data-action="delete-object">删除</button>`:`<span>${tool==='bounds'?'拖动边角调整房屋范围；拖动虚线框可移动。':'拖动标识移动；选中房间后，拖动边角即可缩放。'}</span>`}</div><div class="canvas-caption">${f.rooms.length} 个房间 · ${f.markers.length} 处家具 / 设施<span>已确认的图面资料</span></div></div><aside class="annotation-controls">${recognitionPanel(f)}${floorDataPanel(f)}<section class="panel direction-panel"><div><span class="tiny-index">EIGHT DIRECTIONS</span><h3>确认八个方位</h3><p>把北向转到图上正确的位置，<br>其余七个方位会一起更新。</p></div>${compass(f.north)}<label class="field"><span>调整图上的北向</span><input type="range" id="north-range" min="0" max="359" value="${f.north}" aria-label="图上北向旋转角度"></label><div class="direction-presets eight-presets">${[[0,'上'],[45,'右上'],[90,'右'],[135,'右下'],[180,'下'],[225,'左下'],[270,'左'],[315,'左上']].map(([v,t])=>`<button data-north="${v}" class="${f.north===v?'active':''}">北在${t}</button>`).join('')}</div><label class="check"><input type="checkbox" id="direction-confirm" ${f.directionConfirmed?'checked':''}>我已核实并确认八方位</label><small>北、东北、东、东南、南、西南、西、西北</small></section><div class="drawing-help"><p>矩形：选中后拖动四角缩放。<br>不规则房间：沿拐角点选后闭合。<br>轮廓顶点也可以再次拖动调整。</p><label class="check"><input type="checkbox" id="floor-confirm" ${f.confirmed?'checked':''}>我已核对房屋范围与图面标注</label></div></aside></div>`;}

function goalPicker(){return `<div class="goal-grid">${Object.entries(GOALS).map(([k,v])=>`<button data-goal="${k}" class="goal ${draft.goals.includes(k)?'selected':''}" aria-pressed="${draft.goals.includes(k)}"><span>${v}</span>${draft.goals.includes(k)?`<b>${draft.goals.indexOf(k)+1}</b>`:icon('plus',15)}</button>`).join('')}</div><p class="hint">选择顺序就是优先级；再次点击可取消，最多选择三项。</p>`;}
function tierPicker(){return `<div class="tier-grid">${Object.entries(TIERS).map(([k,t])=>`<button data-tier="${k}" ${draft.finish==='shell'&&k!=='large'?'disabled':''} class="tier ${draft.tier===k?'selected':''}" aria-pressed="${draft.tier===k}"><span class="tier-radio"></span><h3>${t.name}</h3><b>${t.sub}</b><p>${t.text}</p></button>`).join('')}</div>${draft.finish==='shell'?'<p class="hint">毛坯需要硬装规划，当前选择大改。</p>':''}`;}

function needsStep(){const b=draft.birth;return `<div class="owner-entry-strip"><strong>户主八字 · 知星排盘</strong><button class="text-link" data-action="focus-birth">填写 / 查看排盘 ↓</button><a href="https://zhixng.cn/app.html?from=guanzhai" target="_blank" rel="noopener noreferrer">去知星看个人解读 ↗</a></div><div class="needs-layout"><div><section class="panel"><span class="tiny-index">01 / INTENTION</span><h2>你最想改善什么？</h2>${goalPicker()}</section><section class="panel"><span class="tiny-index">02 / BOUNDARY</span><h2>让改变，在你接受的范围内</h2>${tierPicker()}<div class="form-grid">${field('软装与调整预算上限（元）',input('budget',draft.budget,'type="number" min="0" max="10000000"'))}${field('常住人数',input('residents',draft.residents,'type="number" min="1" max="30"'))}${field('必须保留 / 不能动的部分',`<textarea data-field="keep" rows="3" maxlength="600" placeholder="例如：保留现有书桌，不移动客厅沙发。也请在图上锁定对应物品。">${esc(draft.keep)}</textarea>`,true)}</div><p class="hint">文字条件会列入核对清单；图上锁定的区域与物品会直接排除移动。</p></section></div><aside><section class="panel birth-panel"><div class="panel-title"><div><span class="tiny-index">03 / PERSONAL</span><h2>户主八字排盘</h2></div>${icon('compass',30)}</div><p>在观宅内使用知星排盘内核，计算四柱并结合住宅方位解读。填写后可直接预览排盘结果。</p><label class="switch-row"><span>启用知星排盘内核 <small>可选</small></span><input type="checkbox" id="birth-enable" ${b.enabled?'checked':''}></label>${b.enabled?`<div class="birth-fields"><p class="hint">当前支持公历、中国大陆出生地点；时间按北京时间录入。</p>${field('公历出生日期',`<input type="date" data-birth="date" value="${esc(b.date)}" min="1901-01-01" max="${new Date().toISOString().slice(0,10)}">`)}${field('出生时间',`<input type="time" data-birth="time" value="${esc(b.time)}" ${b.unknown?'disabled':''}>`)}<label class="check"><input type="checkbox" data-birth="unknown" ${b.unknown?'checked':''}>时辰不详</label>${field('八宅命卦计算口径（选填）',`<select data-birth="sex">${options({'':'不计算命卦',男:'传统男命口径',女:'传统女命口径'},b.sex||'')}</select>`)}${field('出生城市',`<input data-birth="city" value="${esc(b.city)}" placeholder="例如：杭州" maxlength="30">`)}<p class="hint">出生资料与结果只在本浏览器处理。时辰不详时，不生成时柱或精确个人定向。</p><button class="btn outline" data-action="preview-birth">预览户主排盘</button></div>`:`<div class="birth-empty">${icon('leaf',32)}<p>先看住宅，也可以。<br>不填写八字，不影响基础分析。</p></div>`}</section><div class="aside-note">${icon('lock',16)}<p>你决定提供哪些资料。可以在宅档中关闭八字参考并移除出生信息。</p></div></aside></div>`;}
function birthResult(b){if(!b)return '';return `<div class="bazi-result"><div class="pillars">${['year','month','day','hour'].map((k,i)=>`<div><small>${['年柱','月柱','日柱','时柱'][i]}</small><b>${b.pillars[k]?esc(b.pillars[k].stem+b.pillars[k].branch):'—'}</b></div>`).join('')}</div><p>${esc(b.note)}</p>${b.solar?.lonSource?.startsWith('default')?'<p class="note-warn">出生地未精确匹配，经度采用 120°E；请核对城市后再参考结果。</p>':''}${b.boundaries.length?'<p class="note-warn">接近时间分界：'+b.boundaries.map(x=>esc(x.type)).join('、')+'，请核实出生时间。</p>':''}</div>`;}
function confirmStep(){let b=null;try{b=computeBirth(draft.birth,window.BaziEngine);}catch{}return `<div class="confirm-layout"><div class="drawing-panel">${floorTabs(draft.floors,fi,true)}${floor()?canvas(floor(),{show:true}):''}</div><div class="panel"><div class="eyebrow">YOUR HOME FILE</div><h2>${esc(draft.name||'未命名宅档')}</h2><dl class="summary-list"><div><dt>住宅类型</dt><dd>${({apartment:'城市商品房',villa:'别墅 / 多层住宅',self:'自建房 / 带院住宅'})[draft.type]}</dd></div><div><dt>图面资料</dt><dd>${draft.floors.length} 层 · ${draft.floors.reduce((n,f)=>n+f.rooms.length,0)} 个房间</dd></div><div><dt>八方位与图面</dt><dd>${draft.floors.every(f=>f.directionConfirmed&&f.confirmed)?'已确认':'尚待确认'}</dd></div><div><dt>目标顺序</dt><dd>${draft.goals.map(k=>GOALS[k]).join('、')}</dd></div><div><dt>调整程度</dt><dd>${TIERS[draft.tier].name} · ${esc(draft.budget||'未定')} 元以内</dd></div></dl>${birthResult(b)}<div class="info-box">本次依据你确认的标注生成基础分析。图中未标出的条件会保留为待核实，不补造房屋信息。</div></div></div>`;}
function card(h,select=false){const ready=h.reportRevision>0&&!validate(h).length;return `<article class="house-card"><button class="house-thumb" data-open="${h.id}" aria-label="打开${esc(h.name)}"><img src="${h.floors[0]?.image||'./assets/sample-plan.svg'}" alt="${esc(h.name)}户型"><span class="badge">${h.example?'示例宅档':h.mode==='home'?'现住房':'候选房'}</span><div class="thumb-north">N ↑</div></button><div class="house-card-body"><div class="card-title"><h3>${esc(h.name||'未命名宅档')}</h3><button class="icon-btn" data-delete="${h.id}" aria-label="删除${esc(h.name)}">${icon('trash',16)}</button></div><p>${h.area?esc(h.area)+' ㎡ · ':''}${h.floors.length} 层 · ${ready?'已有分析':'待完善草稿'}</p><div class="card-actions"><button class="text-link" data-open="${h.id}">${ready?'查看分析':'继续完善'} ${icon('arrow',15)}</button>${select?`<label class="compare-check"><input type="checkbox" data-compare="${h.id}" ${compareIds.has(h.id)?'checked':''} ${ready?'':'disabled'}> 加入比较</label>`:''}</div></div></article>`;}
function empty(title,text,action='新建宅档'){return `<div class="empty-state">${icon('house',52)}<h2>${title}</h2><p>${text}</p><button class="btn primary" data-new="home">${icon('plus',16)} ${action}</button><button class="text-link" data-action="demo">用示例体验 ${icon('arrow',15)}</button></div>`;}
function archive(){return `<section class="workspace"><div class="page-heading"><div><div class="eyebrow">HOME ARCHIVE / 一宅一案</div><h1>我的宅档</h1><p>每一次了解，都从自己的空间开始。</p></div><button class="btn primary" data-new="home">${icon('plus',17)} 新建宅档</button></div>${houses.length?`<div class="archive-toolbar"><span>${houses.length} 份宅档 · 保存在本机</span><button class="btn outline" data-action="compare-now" ${compareIds.size<2?'disabled':''}>比较所选 ${compareIds.size?`(${compareIds.size})`:''} ${icon('compare',16)}</button></div><div class="house-grid">${houses.map(h=>card(h,true)).join('')}</div><p class="hint">选择 2–3 份已完成分析的宅档进行比较；可跨现住房与候选房选择。</p>`:empty('给你的家，留一份档案','上传户型、确认八方位，让关于家的思考有迹可循。')}</section>`;}
function readBirth(h){try{return computeBirth(h.birth,window.BaziEngine);}catch{return null;}}
function report(){const h=active();if(!h)return empty('还没有选择宅档','先建立一份住宅档案。');try{analyse(h);}catch{return empty('这份宅档还需完善','请从我的宅档继续确认图面与方位。');}const b=readBirth(h),f=h.floors[Math.min(fi,h.floors.length-1)];return `<section class="workspace report-workspace"><div class="breadcrumb"><a href="#archive">我的宅档</a><span>/</span>住宅解读</div><div class="page-heading"><div><h1>${esc(h.name)}<span class="title-seal">宅</span></h1></div><button class="btn ghost" data-edit="${h.id}">编辑宅档</button></div>${personalizedReport(h,b)}<details class="report-drawing report-reference" id="report-drawing"><summary>查看户型与标注</summary>${floorTabs(h.floors,Math.min(fi,h.floors.length-1))}${canvas(f,{show:overlay})}<button class="text-link" data-action="toggle-overlay">${overlay?'查看原图':'显示标注'}</button></details><div class="report-bottom"><div><h2>把建议放回图上看看</h2><p>保留原图，比较调整前后的摆法。</p></div><button class="btn primary" data-action="start-plan">查看布局方案 →</button></div><details class="report-reference reading-basis"><summary>这份解读依据什么</summary><p>方位取象参考<a href="https://ctext.org/book-of-changes/shuo-gua/zhs" target="_blank" rel="noopener noreferrer">《周易·说卦》</a>；砂水取象参考<a href="https://www.chinavalue.net/article/2015/8/12/1192349.html" target="_blank" rel="noopener noreferrer">金锁玉关八卦整理</a>；房门与安床关系参考<a href="https://www.diancang.xyz/xuanxuewushu/11591/230356.html" target="_blank" rel="noopener noreferrer">《八宅明镜》安床论</a>。具体摆法结合你的房间、家具、预算和保留条件安排。</p><p>本次依据户型标注解读；宅外环境与施工尺寸需现场确认。传统文化建议不保证财运、健康或关系结果。</p></details>${recommend()}</section>`;}
function compare(){const selected=houses.filter(h=>compareIds.has(h.id)&&!validate(h).length);if(selected.length<2)return empty('至少选择两套住宅','在我的宅档中勾选已完成分析的房屋。');const rows=[['空间情况',h=>`${metrics(h).rooms} 个标注空间 / ${metrics(h).bedrooms} 个卧室`],['居住目标',h=>h.goals.map(k=>GOALS[k]).join('、')],['值得保留',h=>metrics(h).good.map(f=>f.title).join('；')],['重点取舍',h=>metrics(h).attention.map(f=>f.title).join('；')||'现有标注未触发额外观察，不等同于没有问题'],['待核实',h=>metrics(h).unknown.map(f=>f.title).join('；')],['改动范围',h=>`${TIERS[h.tier].name} · ${h.budget||'未定'} 元预算上限`],['个人参考',h=>h.birth.enabled?'已启用户主八字文化参考':'未启用']];return `<section class="workspace"><div class="breadcrumb"><a href="#archive">我的宅档</a><span>/</span>候选比较</div><div class="page-heading"><div><div class="eyebrow">SIDE BY SIDE / 看清取舍</div><h1>好房子，也要适合你的生活。</h1><p>比较相同条件，把未知留在明处。</p></div><button class="btn ghost" data-action="back-archive">重新选择</button></div><div class="compare-table-wrap"><table class="compare-table"><thead><tr><th>比较维度</th>${selected.map(h=>`<th><img src="${h.floors[0].image}" alt="${esc(h.name)}户型"><h2>${esc(h.name)}</h2><button class="text-link" data-open="${h.id}">查看完整分析 ↗</button></th>`).join('')}</tr></thead><tbody>${rows.map(([name,get])=>`<tr><th scope="row">${name}</th>${selected.map(h=>`<td>${esc(get(h))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="info-box">此处比较的是已确认的图面与各自需求。目标不同的宅档需先统一目标后再讨论适配；缺少资料不会获得更高评价，也不直接生成综合排名。</div></section>`;}
function planner(){if(!draft)return '';return `<section class="workspace compact-planner"><div class="page-heading"><div><h1>定制布局</h1><p>按目标与预算生成概念摆放方案。</p></div></div><section class="panel">${goalPicker()}<div class="form-grid">${field('改造范围',`<select data-field="tier">${options(Object.fromEntries(Object.entries(TIERS).map(([k,v])=>[k,v.name+' · '+v.sub])),draft.tier)}</select>`)}${field('预算上限（元）',input('budget',draft.budget,'type="number" min="0" max="10000000"'))}</div><p class="hint">原图与锁定物件保留。没有家具尺寸，位置只作概念候选。</p><button class="btn primary" data-action="generate-plan">生成布局方案 →</button></section></section>`;}
function getPlan(){return houses.flatMap(h=>h.plans||[]).find(p=>p.id===planId);}
function planView(){const p=getPlan();if(!p)return empty('还没有布局方案','先从一套已分析的住宅开始。');const h=houses.find(h=>h.id===p.houseId),idx=Math.min(fi,p.floors.length-1),f=p.floors[idx];return `<section class="workspace"><div class="breadcrumb"><a href="#plans">我的方案</a><span>/</span>${esc(p.houseName)}</div><div class="page-heading"><div><div class="eyebrow">${p.tierLabel||TIERS[p.tier].name}方案 / ${p.status==='implemented'?'已标记实施':'待选择'}</div><h1>让${GOALS[p.goals[0]].slice(0,2)}，有一处安放。</h1><p>${esc(p.houseName)} · ${p.goals.map(g=>GOALS[g]).join(' / ')}</p></div><div class="heading-actions"><button class="btn ghost" data-action="print-plan">${icon('download',16)} 打印 / 保存 PDF</button><button class="btn primary" data-action="adopt-plan">${p.status==='implemented'?'改为待选择':'标记已实施'} ${icon('check',16)}</button></div></div>${h?.revision!==p.revision?'<div class="info-box">宅档已更新：这份方案保留生成当时的图面与条件。请根据最新宅档重新推演，勿将旧方案当作当前结论。</div>':''}${floorTabs(p.floors,idx)}<div class="before-after"><div><div class="drawing-label"><b>调整前</b><span>生成时的现状</span></div><div class="drawing-panel">${canvas(f,{show:true})}</div></div><div><div class="drawing-label"><b>调整后 · ${p.layoutMode==='metric'?'尺寸候选':'概念'}</b><span>箭头：移动候选 / 虚线：分区讨论</span></div><div class="drawing-panel">${canvas(f,{show:true,plan:p,after:true})}</div></div></div><p class="hint">底图保持不变，叠层仅表示建议位置；原图里的家具不会被抹除。实际尺寸、通行与施工条件仍需核实。</p>${precisionResult(p)}<div class="plan-detail-layout"><div><div class="section-heading compact"><div class="eyebrow">一步一步，安排新的日常</div><h2>你的调整清单</h2></div>${p.actions.map((a,i)=>`<article class="action-card"><span class="action-number">${String(i+1).padStart(2,'0')}</span><div><small>${esc(a.where)}</small><h3>${esc(a.title)}</h3><p>${esc(a.text)}</p><span class="source-tag">${esc(a.source)}</span></div></article>`).join('')}</div><aside><section class="palette-card"><div class="eyebrow">SOFT FURNISHINGS</div><h2>一组柔和的呼应</h2><div class="swatches">${p.style.colors.map(c=>`<div style="background:${c}"></div>`).join('')}</div><h3>${p.style.names}</h3><p>${p.style.material}，承载${p.style.metaphor}的意象。</p><small>${esc(p.styleBasis||'配色是可选的文化与审美线索，不是喜用神结论或结果保证。')}</small></section><div class="info-box">${esc(p.note)} 标记“已实施”仅记录你的选择，不覆盖原始宅档；实际布局变化请在宅档中更新。</div></aside></div></section>`;}
function plans(){const all=houses.flatMap(h=>h.plans||[]).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return `<section class="workspace"><div class="page-heading"><div><div class="eyebrow">SPACE JOURNAL / 日常的另一种可能</div><h1>我的方案</h1><p>保留每一种选择，也保留改变的理由。</p></div><button class="btn outline" data-action="open-layout">从宅档创建方案 ${icon('plus',16)}</button></div>${all.length?`<div class="house-grid">${all.map(p=>`<article class="house-card"><button class="house-thumb" data-plan="${p.id}"><img src="${p.floors[0].image}" alt="${esc(p.houseName)}方案"><span class="badge">${p.tierLabel||TIERS[p.tier].name} · ${p.status==='implemented'?'已实施':'待选择'}</span></button><div class="house-card-body"><div class="card-title"><h3>${esc(p.houseName)}</h3><button class="icon-btn" data-delete-plan="${p.id}" aria-label="删除方案">${icon('trash',16)}</button></div><p>${p.goals.map(g=>GOALS[g]).join(' · ')}</p><button class="text-link" data-plan="${p.id}">查看前后对照 ${icon('arrow',15)}</button></div></article>`).join('')}</div>`:empty('让改变，从一张图开始','先完成住宅分析，再按你的需求创建布局方案。')}</section>`;}
async function sampleHouse(mode='home'){
  const h=newHouse(mode);h.name=mode==='home'?'松风居 · 示例':'南窗居 · 示例';h.finish='furnished';h.area=96;h.goals=['work','rest'];h.example=true;
  const f=newFloor('./assets/sample-plan.svg');f.bounds={x:.085,y:.087,w:.82,h:.813};
  f.rooms=[['卧室','bedroom',.095,.098,.29,.32],['书房','study',.095,.447,.29,.30],['客厅','living',.41,.446,.266,.386],['餐厅','dining',.41,.10,.266,.30],['厨房','kitchen',.70,.10,.19,.33],['卫生间','bath',.70,.48,.19,.17],['阳台','balcony',.095,.786,.29,.10]].map(([name,type,x,y,w,hh])=>({id:uid(),name,type,x,y,w,h:hh,locked:false}));
  f.markers=[['door',.532,.898],['window',.21,.088],['window',.54,.088],['bed',.24,.24],['desk',.20,.50],['sofa',.54,.49],['stove',.82,.13]].map(([type,x,y])=>({id:uid(),type,x,y,locked:false}));
  f.directionConfirmed=true;f.confirmed=true;f.boundary=[{x:.085,y:.087},{x:.905,y:.087},{x:.905,y:.91},{x:.4,y:.91},{x:.4,y:.78},{x:.085,y:.78}];f.rooms=f.rooms.filter(r=>r.type!=='balcony');for(const r of f.rooms)r.measurements={width:'未知',depth:'未知'};f.extents={width:'未知',height:'未知'};h.floors=[f];Object.assign(h,{flowVersion:4,housingCity:'杭州',district:'西湖区',community:'演示小区（虚构）',bedrooms:2,livingrooms:2,summaryConfirmed:true});return h;
}
async function upload(files){
  if(!files.length)return;
  const valid=['image/png','image/jpeg','image/webp'];
  if(draft.floors.length+files.length>8)throw Error('每套住宅最多保存 8 张分层户型图。');
  const loaded=[];
  for(const file of files){
    if(!valid.includes(file.type))throw Error('只接受 JPG、PNG 或 WEBP 户型图。暂不支持视频、PDF 或其他文件。');
    if(file.size>10*1024*1024)throw Error('单张户型图不能超过 10 MB。');
    const url=URL.createObjectURL(file);
    try{
      const img=new Image();img.src=url;await img.decode();
      if(img.naturalWidth<100||img.naturalHeight<100)throw Error('户型图太小，请选择至少 100 × 100 像素的清楚图片。');
      const scale=Math.min(1,2200/Math.max(img.naturalWidth,img.naturalHeight)),c=document.createElement('canvas');c.width=Math.round(img.naturalWidth*scale);c.height=Math.round(img.naturalHeight*scale);
      const ctx=c.getContext('2d');ctx.fillStyle='#f3f0e7';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);
      const f=newFloor(c.toDataURL('image/jpeg',.88),`${draft.floors.length+loaded.length+1} 层`,c.width,c.height);try{f.recognition=await recognizeImage(f.image);}catch{f.recognition={candidates:[],parameters:{gap:8},note:'本次识图未完成，请到图面重试或手动勾线。'};}if(draft.furnitureConsent&&serviceStatus.vision){try{f.furnitureRecognition=await service('furniture',{image:f.image});}catch{f.furnitureRecognition={status:'failed',objects:[]};}}loaded.push(f);
    }finally{URL.revokeObjectURL(url);}
  }
  draft.floors.push(...loaded);draft.example=false;touch();render();toast(`已添加 ${loaded.length} 张户型图，请继续确认八方位与图面。`);
}
async function leaveEditor(){if(dirty&&draft){await persist(draft);dirty=false;}}
async function navigate(p){await leaveEditor();setPage(p);}
async function startNew(mode){await leaveEditor();draft=newHouse(mode);draft.flowVersion=4;fi=0;selection=null;tool='select';sketch=[];step=0;dirty=false;setPage('editor');}
async function openHouse(id,forceEdit=false){await leaveEditor();const h=houses.find(x=>x.id===id);if(!h)return;currentId=id;fi=0;selection=null;reportFilter='all';overlay=true;
  if(forceEdit||!h.reportRevision||validate(h).length){draft=structuredClone(h);draft.flowVersion=4;draft.summaryConfirmed=false;dirty=false;step=forceEdit?0:Math.min(h.intakeStep||0,10);tool=step===5?'boundary':'select';setPage('editor');}else setPage('report');
}
async function next(){
 if(step===0){const errors=validBirth(draft.birth);if(errors.length)throw Error(errors[0]);if(draft.birth.enabled)computeBirth(draft.birth,window.BaziEngine);}
 if(step===0){draft.autoFavorable=favorableReference(readBirth(draft));draft.favorable='';draft.favorableSource='';}
 const error=stageError(draft,step);if(error)throw Error(error);
 if(step===10){for(let i=0;i<10;i++){const error=stageError(draft,i);if(error){step=i;render();throw Error(error);}}for(const f of draft.floors)f.confirmed=true;if(!draft.name.trim())draft.name=draft.community||'我的住宅';draft.goals=['balance'];draft.reportRevision=draft.revision;const errors=validate(draft);if(errors.length)throw Error(errors[0]);await persist(draft);dirty=false;currentId=draft.id;fi=0;setPage('report');toast('住宅分析已生成。阅读后选择最多三项加强方向。');return;}
 step++;selection=null;sketch=[];tool=step===5?'boundary':'select';overlay=true;render();window.scrollTo({top:0,behavior:'instant'});
}
function privacyConsent(){modal('加入户主八字参考',`<p>观宅会在你的浏览器内处理出生日期、时间与城市，用于排盘和个人文化参考。资料保存在本机宅档，不会发送给知星或其他服务。</p><p>你可以随时关闭此项并删除出生资料。不填写也可以分析住宅。</p>`,`<button class="btn ghost" data-close>暂不填写</button><button class="btn primary" id="birth-consent">同意并填写</button>`);$('#birth-consent').onclick=()=>{draft.birth.enabled=true;draft.birth.consent=true;touch();$('#modal').close();render();};}
const handlers={
 'focus-birth':()=>{$('.birth-panel')?.scrollIntoView({behavior:'smooth',block:'start'});},
 'report-birth':()=>{draft=structuredClone(active());dirty=false;step=0;setPage('editor');$('.birth-panel')?.scrollIntoView({block:'start'});},
 'preview-birth':()=>{const b=computeBirth(draft.birth,window.BaziEngine);if(!b)throw Error('请先启用八字并同意填写资料。');modal('户主排盘 · 知星内核',birthResult(b)+'<p>四柱在本机计算。保存宅档后，住宅报告会加入逐房间人宅参考。</p>','<button class="btn primary" data-close>返回填写</button>');},
  'privacy':()=>modal('资料留在你的浏览器',`<p>户型、标注、出生资料与方案仅存放在当前浏览器的本机数据库中。不使用地图或家具识别时，资料只在本机处理。启用地图查询会发送住宅地址；同意识别家具会发送户型图。出生资料不发送给这两项服务。推荐入口只跳转产品页面，不携带出生或户型资料。</p><p>更换浏览器、清理网站数据或使用隐私模式，可能导致宅档无法保留。你可以从“我的宅档”删除对应房屋；其出生资料和全部方案会一并移除。</p>`,`<button class="btn primary" data-close>知道了</button>`),
  'about':()=>modal('关于这份分析',`<p>观宅当前是基础交互测试版。上传后由你确认八方位、房间与家具；图面关系与方案由明确规则生成，已加入本机封闭轮廓识别及分层规则深度解读，不调用 AI。</p><p>八字基础排盘采用独立保存的知星确定性内核，文化意象配色不是喜用神判断。仅凭八方位不生成精确飞星盘，传统内容不保证财富、健康或关系结果。</p>`,`<button class="btn primary" data-close>了解</button>`),
  'demo':async()=>{await leaveEditor();let h=houses.find(x=>x.example&&x.name==='松风居 · 示例'&&x.flowVersion===4);if(!h){h=await sampleHouse();h.reportRevision=h.revision;await persist(h);}await openHouse(h.id);},
  'sample-upload':async()=>{const sample=await sampleHouse(draft.mode);draft.floors=sample.floors;draft.name=draft.name||sample.name;draft.area=draft.area||sample.area;draft.example=true;draft.finish=draft.finish||'furnished';for(const f of draft.floors){f.directionConfirmed=false;f.confirmed=false;f.geometryConfirmed=false;}for(const f of draft.floors){f.rooms=[];f.markers=[];}fi=0;touch();step=5;tool='boundary';render();},
  'save-draft':async()=>{if(!draft.name.trim())draft.name=draft.community||'未完成的宅档';await persist(draft);dirty=false;toast('草稿已保存到我的宅档。');},
  'next':next,
  'prev':async()=>{if(step){step--;selection=null;sketch=[];tool=step===5?'boundary':'select';render();}else await navigate('home');},
  'toggle-overlay':()=>{overlay=!overlay;render();},
  'delete-object':()=>{const f=floor();f.rooms=f.rooms.filter(r=>r.id!==selection);f.markers=f.markers.filter(m=>m.id!==selection);selection=null;f.confirmed=false;touch();render();},
  'compare-now':()=>{if(compareIds.size<2)throw Error('请至少选择两套已完成分析的住宅。');setPage('compare');},
  'back-archive':()=>navigate('archive'),
  'start-plan':()=>{draft=structuredClone(active());draft.layoutMode='concept';dirty=false;setPage('planner');},
  'back-report':async()=>{await leaveEditor();setPage('report');},
  'open-layout':async()=>{await leaveEditor();if(houses.some(h=>h.reportRevision&&!validate(h).length)){setPage('archive');toast('选择一套住宅，在分析报告中进入“定制布局”。');}else await startNew('home');},
  'generate-plan':async()=>{draft.summaryConfirmed=true;const errors=validate(draft);if(errors.length)throw Error(errors[0]);const b=computeBirth(draft.birth,window.BaziEngine);const p=makePlan(draft,draft.tier,b);const ref=colorReference(draft,b);p.style=ref.style;p.styleBasis=ref.label+'：'+ref.basis;p.actions=p.actions.filter(a=>a.kind!=='decor');p.actions.push({title:'配色与参考风格',where:'可调整区域',text:ref.style.names+'；'+ref.style.material+'。'+ref.basis,source:ref.label,kind:'decor'});draft.plans.push(p);draft.reportRevision=draft.revision;await persist(draft);dirty=false;currentId=draft.id;planId=p.id;fi=0;setPage('plan');toast('布局方案已保存，原始户型保持不变。');},
  'adopt-plan':async()=>{const p=getPlan(),h=houses.find(h=>h.id===p.houseId),copy=structuredClone(h);const target=copy.plans.find(x=>x.id===p.id);target.status=p.status==='implemented'?'draft':'implemented';await persist(copy);render();toast(target.status==='implemented'?'已记录实施状态；实际布局变化可在宅档中更新。':'已改为待选择。');},
  'print-plan':()=>window.print()
};
function bind(){
  $('#app').onclick=async event=>{
    const b=event.target.closest('button,a,input[data-compare]');if(!b)return;
    try{
      if(b.matches('a[href^="#"]')){event.preventDefault();await navigate(b.hash.slice(1));return;}
      if(b.dataset.new){await startNew(b.dataset.new);return;}
      if(b.dataset.action){await handlers[b.dataset.action]?.();return;}
      if(b.dataset.open){await openHouse(b.dataset.open);return;}
      if(b.dataset.edit){await openHouse(b.dataset.edit,true);return;}
      if(b.dataset.step!==undefined){step=+b.dataset.step;render();return;}
      if(b.dataset.floor!==undefined){fi=+b.dataset.floor;selection=null;sketch=[];tool='select';render();return;}
      if(b.dataset.north!==undefined){floor().north=+b.dataset.north;floor().directionConfirmed=false;touch();render();return;}
      if(b.dataset.tool){tool=b.dataset.tool;sketch=[];selection=null;overlay=true;render();return;}
      if(b.dataset.select){if(page==='editor'&&['boundary','polygon'].includes(tool))return;selection=b.dataset.select;if(page==='editor')render();else if(page==='report'){$$('.room-region,.furniture').forEach(el=>el.classList.toggle('selected',el.dataset.select===selection));const el=$$('[data-finding-room]').find(x=>x.dataset.findingRoom===selection);el?.scrollIntoView({behavior:'smooth',block:'center'});el?.classList.add('highlight');setTimeout(()=>el?.classList.remove('highlight'),1800);}return;}
      if(b.dataset.layoutMode){draft.layoutMode=b.dataset.layoutMode;touch();render();return;}
      if(b.dataset.improveGoal){const h=active(),k=b.dataset.improveGoal,goals=h.improvementGoals||[];if(!goals.includes(k)&&goals.length>=3){toast('最多选择三项，请先取消一项。');return;}h.improvementGoals=goals.includes(k)?goals.filter(x=>x!==k):[...goals,k];h.improvementResult=null;await persist(h);render();return;}
      if(b.dataset.zoom&&$('.drawing-viewport')){const v=$('.drawing-viewport').viewportController;if(b.dataset.zoom==='reset')v?.reset();else v?.zoom(b.dataset.zoom==='in'?1.25:1/1.25);return;}
      if(b.dataset.zoom){const el=$('.zoom-sheet'),old=Number(el.dataset.zoom||1),n=b.dataset.zoom==='reset'?1:clamp(old+(b.dataset.zoom==='in'?.25:-.25),1,3);el.dataset.zoom=n;el.style.width=(n*100)+'%';return;}
      if(b.dataset.goal){const k=b.dataset.goal;draft.goals=draft.goals.includes(k)?draft.goals.filter(x=>x!==k):draft.goals.length<3?[...draft.goals,k]:draft.goals;if(!draft.goals.includes(k)&&draft.goals.length===3)toast('最多选择三项目标，可取消后调整顺序。');touch();render();return;}
      if(b.dataset.fixStep!==undefined){draft=structuredClone(active());dirty=false;step=Number(b.dataset.fixStep);fi=Math.max(0,draft.floors.findIndex(f=>f.id===b.dataset.fixFloor));selection=b.dataset.fixRoom||null;tool=step===5?'boundary':'select';sketch=[];setPage('editor');return;}
      if(b.dataset.reviewRoom){selection=b.dataset.reviewRoom;tool='select';render();return;}
      if(b.dataset.reviewMarker){selection=b.dataset.reviewMarker;tool='select';render();return;}
      if(b.dataset.finish){draft.finish=b.dataset.finish;touch();render();return;}
      if(b.dataset.addMarker){addMarker(b.dataset.addMarker);return;}
      if(b.dataset.tier){draft.tier=b.dataset.tier;touch();render();return;}
      if(b.dataset.filter){reportFilter=b.dataset.filter;render();return;}
      if(b.dataset.locate){const h=active();fi=h.floors.findIndex(f=>f.id===b.dataset.locateFloor);selection=b.dataset.locate;overlay=true;render();const drawing=$('.report-drawing');if(drawing)drawing.open=true;$('.report-drawing')?.scrollIntoView({behavior:'smooth',block:'center'});return;}
      if(b.dataset.plan){planId=b.dataset.plan;fi=0;setPage('plan');return;}
      if(b.dataset.delete){const h=houses.find(h=>h.id===b.dataset.delete);confirmAction('删除这份宅档？',`将移除「${esc(h.name)}」的户型、出生资料与全部方案。此操作无法撤回。`,async()=>{await removeHouse(h.id);houses=houses.filter(x=>x.id!==h.id);compareIds.delete(h.id);if(draft?.id===h.id){draft=null;dirty=false;}render();toast('宅档已从本机删除。');});return;}
      if(b.dataset.deletePlan){const id=b.dataset.deletePlan,h=houses.find(h=>h.plans.some(p=>p.id===id));confirmAction('删除这份方案？','只移除这份方案，保留原始宅档。',async()=>{const copy=structuredClone(h);copy.plans=copy.plans.filter(p=>p.id!==id);await persist(copy);render();});return;}
      if(b.dataset.removeFloor!==undefined){draft.floors.splice(+b.dataset.removeFloor,1);fi=0;touch();render();return;}
    }catch(e){toast(e.message||'操作未完成，请重试。');}
  };
  $$('[data-field]').forEach(el=>el.oninput=()=>{let value=el.value;if(el.type==='number'&&value!==''){const min=Number(el.min||0),max=Number(el.max||10000000);value=clamp(value,min,max);}draft[el.dataset.field]=value;if(['housingCity','district','community'].includes(el.dataset.field))draft.environment=null;touch();});
  $$('[data-birth]').forEach(el=>el.oninput=()=>{draft.birth[el.dataset.birth]=el.type==='checkbox'?el.checked:el.value;touch();if(el.dataset.birth==='unknown')render();});
  $('#birth-enable')?.addEventListener('change',e=>{if(e.target.checked){e.target.checked=false;privacyConsent();}else{draft.birth={enabled:false,consent:false,date:'',time:'',city:'',unknown:false};touch();render();}});
  $('#file-input')?.addEventListener('change',async e=>{try{await upload([...e.target.files]);}catch(err){toast(err.message);e.target.value='';}});
  const drop=$('#drop-zone');if(drop){drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragover');};drop.ondragleave=()=>drop.classList.remove('dragover');drop.ondrop=async e=>{e.preventDefault();drop.classList.remove('dragover');try{await upload([...e.dataTransfer.files]);}catch(err){toast(err.message);}};}
  $('#north-range')?.addEventListener('input',e=>{floor().north=+e.target.value;floor().directionConfirmed=false;touch();$('#direction-confirm').checked=false;$$('.compass').forEach(c=>c.style.setProperty('--north',`${floor().north}deg`));$$('[data-north]').forEach(b=>b.classList.toggle('active',+b.dataset.north===floor().north));});
  $('#direction-confirm')?.addEventListener('change',e=>{floor().directionConfirmed=e.target.checked;touch();render();});
  $('#floor-confirm')?.addEventListener('change',e=>{if(e.target.checked&&!floor().rooms.length){e.target.checked=false;toast('请至少标注一个房间后再确认。');return;}floor().confirmed=e.target.checked;touch();render();});
  bindAdvanced();
  $('#marker-tool')?.addEventListener('change',e=>{if(e.target.value)addMarker(e.target.value);});
  $$('[data-compare]').forEach(el=>el.onchange=()=>{if(el.checked&&compareIds.size>=3){el.checked=false;toast('一次最多比较三套房源。');return;}if(el.checked)compareIds.add(el.dataset.compare);else compareIds.delete(el.dataset.compare);render();});
  bindIntake();
  setupDrawing();
  setupViewports();
}
function addMarker(type){
 if(!CATALOG[type])return;
 const f=floor();let x=.075,y=.075;
 for(let i=0;i<100;i++){const px=.075+(i%5)*.055,py=.075+Math.floor(i/5)*.055;if(!f.markers.some(m=>Math.hypot(m.x-px,m.y-py)<.03)){x=px;y=py;break;}}
 const m={id:uid(),type,x,y,uiScale:1,locked:!!CATALOG[type].fixed};f.markers.push(m);selection=m.id;f.confirmed=false;tool='select';sketch=[];overlay=true;touch();render();
}
function finishPolygon(){
 if(!validPolygon(sketch)){toast('轮廓需要至少三个有效拐角，线段不能交叉或重叠。');return;}
 const f=floor();if(tool==='boundary'){f.boundary=structuredClone(sketch);f.bounds=polygonBounds(sketch);f.extents=null;f.confirmed=false;draft.summaryConfirmed=false;sketch=[];tool='select';touch();render();return;}const r={id:uid(),measurements:{width:'未知',depth:'未知'},name:`房间 ${f.rooms.length+1}`,type:'other',...polygonBounds(sketch),points:structuredClone(sketch),locked:false};f.rooms.push(r);selection=r.id;sketch=[];tool='select';f.confirmed=false;touch();render();
}
Object.assign(handlers,{
 'add-room':()=>{const f=floor(),r={id:uid(),name:`房间 ${f.rooms.length+1}`,type:'other',measurements:{width:'未知',depth:'未知'},x:f.bounds.x+.02,y:f.bounds.y+.02,w:Math.min(.24,f.bounds.w*.6),h:Math.min(.24,f.bounds.h*.6),locked:false};f.rooms.push(r);selection=r.id;tool='select';sketch=[];f.confirmed=false;overlay=true;touch();render();},
 'undo-point':()=>{sketch.pop();render();},
 'close-polygon':finishPolygon,
 'cancel-polygon':()=>{sketch=[];tool='select';render();},
 'toggle-lock':()=>{const f=floor(),o=f.rooms.find(r=>r.id===selection)||f.markers.find(m=>m.id===selection);if(o){o.locked=!o.locked;touch();render();}},
 'rename-room':()=>{const r=floor().rooms.find(r=>r.id===selection);if(!r)return;modal('房间名称与用途',`${field('名称',`<input id="room-name" value="${esc(r.name)}" maxlength="18">`)}${field('用途',`<select id="room-type">${options(ROOMS,r.type)}</select>`)}`,`<button class="btn ghost" data-close>取消</button><button class="btn primary" id="save-room-name">完成</button>`);$('#save-room-name').onclick=()=>{r.name=$('#room-name').value.trim()||ROOMS[$('#room-type').value];r.type=$('#room-type').value;floor().confirmed=false;floor().geometryConfirmed=false;touch();$('#modal').close();render();};}
});
function setupDrawing(){
 const c=$('#edit-canvas');if(!c)return;let drag=null,changed=false;const blocked=()=>c.closest('.drawing-viewport')?.dataset.gesture==='true'||performance.now()<Number(c.closest('.drawing-viewport')?.dataset.suppressUntil||0);c.cancelInteraction=()=>{if(drag)Object.assign(drag.obj,drag.original);drag=null;};
 const coords=e=>{const r=c.getBoundingClientRect();return {x:clamp((e.clientX-r.left)/r.width,0,1),y:clamp((e.clientY-r.top)/r.height,0,1)};};
 const live=()=>{const tmp=document.createElement('div');tmp.innerHTML=canvas(floor(),{editable:true,show:overlay});c.innerHTML=tmp.firstElementChild.innerHTML;syncAttributes(draft);};
 c.onpointerdown=e=>{
  if(blocked()||e.button!==0||['polygon','scale','boundary'].includes(tool))return;
  const el=e.target.closest('[data-select],[data-handle],[data-vertex]');if(!el)return;
  const id=el.dataset.region||el.dataset.select;
  const obj=id==='$bounds'?floor().bounds:floor().rooms.find(r=>r.id===id)||floor().markers.find(m=>m.id===id);if(!obj)return;
  selection=id;changed=false;drag={obj,id,start:coords(e),original:structuredClone(obj),handle:el.dataset.handle,vertex:el.dataset.vertex};c.setPointerCapture(e.pointerId);e.preventDefault();
 };
 c.onpointermove=e=>{
  if(!drag)return;const p=coords(e),o=drag.original,obj=drag.obj,dx=p.x-drag.start.x,dy=p.y-drag.start.y;
  if(Math.hypot(dx,dy)<.002&&!changed)return;changed=true;
  if(drag.vertex!==undefined){obj.points=structuredClone(o.points);obj.points[Number(drag.vertex)]=snapPoint(p,o.points[(Number(drag.vertex)+o.points.length-1)%o.points.length],null,12/c.getBoundingClientRect().width,step===8?floor().boundary:null,floor().recognition?.walls);Object.assign(obj,polygonBounds(obj.points));}
  else if(drag.handle){const edge=drag.handle;let left=o.x,top=o.y,right=o.x+o.w,bottom=o.y+o.h;if(edge.includes('w'))left=clamp(o.x+dx,0,right-.035);if(edge.includes('e'))right=clamp(o.x+o.w+dx,left+.035,1);if(edge.includes('n'))top=clamp(o.y+dy,0,bottom-.035);if(edge.includes('s'))bottom=clamp(o.y+o.h+dy,top+.035,1);Object.assign(obj,resizeRegion(o,{x:left,y:top,w:right-left,h:bottom-top}));}
  else {const x=clamp(o.x+dx,0,1-(o.w||0)),y=clamp(o.y+dy,0,1-(o.h||0));obj.x=x;obj.y=y;if(o.points)obj.points=o.points.map(p=>({x:p.x+x-o.x,y:p.y+y-o.y}));}
  live();
 };
 c.onpointerup=e=>{
  if(blocked())return;
  if(drag){if(changed){if(drag.obj.points&&!validPolygon(drag.obj.points)){Object.assign(drag.obj,drag.original);toast('这次调整使轮廓交叉或重叠，已恢复原来的形状。');}else{floor().confirmed=false;touch();}}drag=null;render();return;}
  if(tool==='scale'){sketch.push(coords(e));if(sketch.length===2)finishCalibration();else render();return;}
  if(['polygon','boundary'].includes(tool)){const p=snapPoint(coords(e),sketch.at(-1),sketch.length>=3?sketch[0]:null,12/c.getBoundingClientRect().width,tool==='polygon'?floor().boundary:null,floor().recognition?.walls);if(sketch.length>=3&&Math.hypot(p.x-sketch[0].x,p.y-sketch[0].y)<.025){finishPolygon();return;}if(sketch.length&&Math.hypot(p.x-sketch.at(-1).x,p.y-sketch.at(-1).y)<.006)return;if(sketch.length>=30){toast('单个房间最多 30 个拐角，请先闭合轮廓。');return;}sketch.push(p);render();}
 };
 c.onpointercancel=()=>{if(drag){Object.assign(drag.obj,drag.original);syncAttributes(draft);}drag=null;render();};
 c.ondblclick=e=>{if(!['polygon','scale','boundary'].includes(tool)&&e.target.closest('.room-region')){selection=e.target.closest('.room-region').dataset.select;render();}};
 c.onkeydown=e=>{const handle=e.target.closest('[data-handle]');const id=handle?.dataset.region||e.target.closest('[data-select]')?.dataset.select;if(!id||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const obj=id==='$bounds'?floor().bounds:floor().rooms.find(r=>r.id===id)||floor().markers.find(m=>m.id===id);if(!obj)return;const dx=e.key==='ArrowLeft'?-.01:e.key==='ArrowRight'?.01:0,dy=e.key==='ArrowUp'?-.01:e.key==='ArrowDown'?.01:0,old=structuredClone(obj);if(handle){const edge=handle.dataset.handle;let left=old.x,top=old.y,right=old.x+old.w,bottom=old.y+old.h;if(edge.includes('w'))left=clamp(left+dx,0,right-.035);else right=clamp(right+dx,left+.035,1);if(edge.includes('n'))top=clamp(top+dy,0,bottom-.035);else bottom=clamp(bottom+dy,top+.035,1);Object.assign(obj,resizeRegion(old,{x:left,y:top,w:right-left,h:bottom-top}));}else{obj.x=clamp(old.x+dx,0,1-(old.w||0));obj.y=clamp(old.y+dy,0,1-(old.h||0));if(old.points)obj.points=old.points.map(p=>({x:p.x+obj.x-old.x,y:p.y+obj.y-old.y}));}floor().confirmed=false;touch();live();};
}

function finishCalibration(){
 const [a,b]=sketch,f=floor();if(Math.hypot((b.x-a.x)*f.width,(b.y-a.y)*f.height)<5){sketch=[];toast('两个端点太近，请重新选择。');render();return;}
 modal('标定实际长度',field('两个端点间实测距离（米）','<input id="calibration-metres" type="number" min="0.1" max="200" step="0.01" placeholder="例如 3.6">')+'<p>请选择同一平面、没有透视变形的户型图。不要用套内面积反推比例。</p>','<button class="btn ghost" data-close>取消</button><button class="btn primary" id="save-calibration">确认长度</button>');
 $('#save-calibration').onclick=()=>{const metres=Number($('#calibration-metres').value);if(!Number.isFinite(metres)||metres<.1||metres>200){toast('请输入 0.1–200 米之间的实测长度。');return;}f.calibration={a,b,metres,confirmed:true};f.geometryConfirmed=false;f.confirmed=false;sketch=[];tool='select';touch();$('#modal').close();render();};
 $('#modal').addEventListener('close',()=>{if(tool==='scale'){sketch=[];tool='select';render();}},{once:true});
}
function bindAdvanced(){
 $('#geometry-confirm')?.addEventListener('change',e=>{floor().geometryConfirmed=e.target.checked;touch();});
 $('#metric-clearance')?.addEventListener('change',e=>{floor().clearance=clamp(e.target.value,.05,1.5);floor().geometryConfirmed=false;touch();render();});
 $('#facing-degrees')?.addEventListener('input',e=>{floor().facing=e.target.value===''?null:clamp(e.target.value,0,359.9);floor().facingConfirmed=false;$('#facing-confirm').checked=false;touch();});
 $('#facing-confirm')?.addEventListener('change',e=>{if(e.target.checked&&!Number.isFinite(floor().facing)){e.target.checked=false;toast('先填写实测面向角度。');return;}floor().facingConfirmed=e.target.checked;touch();});
}
Object.assign(handlers,{
 'edit-geometry':()=>{fi=0;step=6;setPage('editor');},
 'recognize-plan':async()=>{const f=floor(),gap=Number($('#recognition-gap')?.value??20),threshold=Number($('#recognition-threshold')?.value??165),button=$('[data-action="recognize-plan"]');button.disabled=true;button.textContent='正在提取轮廓…';try{await new Promise(r=>requestAnimationFrame(r));f.recognition=await recognizeImage(f.image,{gap,threshold});touch();render();}finally{if(button.isConnected){button.disabled=false;button.textContent='重新识别';}}},
 'accept-recognition':()=>{const indices=$$('[data-recognition-index]:checked').map(el=>Number(el.dataset.recognitionIndex)),f=floor();if(!indices.length){toast('先勾选需要采用的候选轮廓。');return;}for(const i of indices){const r=f.recognition.candidates[i];f.rooms.push({...structuredClone(r),id:uid(),name:'房间 '+(f.rooms.length+1),locked:false,reviewed:true});}f.recognition.candidates=f.recognition.candidates.filter((_,i)=>!indices.includes(i));f.confirmed=false;f.geometryConfirmed=false;touch();render();toast('已加入所选房间，请核对轮廓并设置名称和用途。');},
 'dismiss-recognition':()=>{floor().recognition.candidates=[];touch();render();},
 'marker-dimensions':()=>{const f=floor(),m=f.markers.find(m=>m.id===selection);if(!m)return;const d=m.dimensions||{};modal(MARKERS[m.type]+' · 实测尺寸',field('宽度（米）','<input id="object-width" type="number" min="0.05" max="30" step="0.01" value="'+(d.width||'')+'">')+field('深度（米）','<input id="object-depth" type="number" min="0.05" max="30" step="0.01" value="'+(d.depth||'')+'">')+field('相对图纸方向','<select id="object-rotation">'+options({0:'宽边沿图纸横向',90:'宽边沿图纸纵向'},d.rotation||0)+'</select>')+'<p>家具按最大矩形外形录入。门窗、柜门或椅子请填写完整开启／使用保留区，并把图上标识拖到该区域中心；此模型不识别铰链。</p>','<button class="btn ghost" data-close>取消</button><button class="btn primary" id="save-dimensions">确认实测尺寸</button>');$('#save-dimensions').onclick=()=>{const width=Number($('#object-width').value),depth=Number($('#object-depth').value);if(![width,depth].every(v=>Number.isFinite(v)&&v>=.05&&v<=30)){toast('长宽须在 0.05–30 米之间。');return;}m.dimensions={width,depth,rotation:Number($('#object-rotation').value),confirmed:true};f.geometryConfirmed=false;f.confirmed=false;touch();$('#modal').close();render();};}
});

function setupViewports(){if(page==='editor'){const drawing=$('.intake-drawing'),bottom=$('.wizard-bottom');if(drawing&&bottom){const overflow=bottom.getBoundingClientRect().bottom-innerHeight+12;if(overflow>0){const box=drawing.getBoundingClientRect(),v=drawing.querySelector('.drawing-viewport'),ratio=v? v.clientWidth/v.clientHeight:1.29;drawing.style.maxWidth=Math.max(130,box.width-overflow*ratio)+'px';}}}if(page==='editor'&&$('.summary-viewport')){const v=$('.summary-viewport'),over=$('.wizard-bottom').getBoundingClientRect().bottom-innerHeight+12;if(over>0){const height=Math.max(110,v.clientHeight-over);v.style.height=height+'px';v.style.width=Math.min(v.clientWidth,height*floor().width/floor().height)+'px';v.style.margin='auto';}}const root=$('.drawing-viewport');if(root)root.viewportController=bindViewport(root,`${page}-${page==='editor'?draft.id:currentId}-${fi}-${step}`,{cancel:()=>$('#edit-canvas')?.cancelInteraction?.()});}
function bindIntake(){
 $('#auto-furniture-consent')?.addEventListener('change',ev=>{draft.furnitureConsent=ev.target.checked;touch();});
 $('#extent-confirm')?.addEventListener('change',ev=>{floor().extents||={};floor().extents.confirmed=ev.target.checked;touch();});
 $('#birth-consent-inline')?.addEventListener('change',ev=>{draft.birth.consent=ev.target.checked;draft.birth.enabled=ev.target.checked;if(!ev.target.checked)draft.birth={enabled:false,consent:false,date:'',time:'',city:'',unknown:false};touch();render();});
 $$('[data-date-part]').forEach(el=>el.onchange=()=>{const b=draft.birth,k=el.dataset.datePart,old=(b.date||'').split('-');b.year||=old[0]||'';b.month||=old[1]||'';b.day||=old[2]||'';b[k]=el.value;const days=new Date(Number(b.year),Number(b.month),0).getDate();if(Number(b.day)>days)b.day='';b.date=b.year&&b.month&&b.day?`${b.year}-${String(b.month).padStart(2,'0')}-${String(b.day).padStart(2,'0')}`:'';touch();render();});
 $('#symbol-scale')?.addEventListener('input',ev=>{const m=floor().markers.find(m=>m.id===selection);if(m){m.uiScale=Number(ev.target.value);touch();const el=$(`[data-select="${m.id}"]`);el?.style.setProperty('--symbol-scale',m.uiScale);}});

 $$('[data-extent]').forEach(el=>el.oninput=()=>{floor().extents||={};floor().extents[el.dataset.extent]=el.value.trim();floor().extents.confirmed=false;if($('#extent-confirm'))$('#extent-confirm').checked=false;floor().extents.source='用户录入，待实测核对';touch();});
 $$('[data-room]').forEach(el=>el.oninput=()=>{const r=floor().rooms.find(r=>r.id===selection);if(!r)return;const k=el.dataset.room;if(['name','type'].includes(k))r[k]=el.value;else{r.measurements||={};r.measurements[k]=el.value.trim();r.measurements.source='用户录入';}const label=$(`[data-select="${r.id}"] span`);if(label)label.innerHTML=esc(r.name)+`<small class="room-measure">${esc(r.measurements?.width||'未知')} × ${esc(r.measurements?.depth||'未知')} 米</small>`;floor().confirmed=false;touch();});
 $('.inline-room')?.addEventListener('pointerdown',e=>e.stopPropagation());
 $('#summary-confirm')?.addEventListener('change',e=>{draft.summaryConfirmed=e.target.checked;dirty=true;});
}
Object.assign(handlers,{
 'go-back':async()=>{if(page==='home'){if(history.length>1)history.back();else toast('当前已是首页。');return;}if(page==='planner'){await navigate('report');return;}if(page==='plan'){await navigate('plans');return;}if(page==='report'||page==='compare'){await navigate('archive');return;}await navigate('home');},
 'summary-details':()=>{const h=draft;modal('全部资料核对',`<p>${esc(h.housingCity)} · ${esc(h.district)} · ${esc(h.community)}<br>${esc(h.area)}㎡ · ${esc(h.bedrooms)}房${esc(h.livingrooms)}厅 · 常住 ${esc(h.residents)} 人<br>${esc(h.budget)} 元预算 · ${TIERS[h.tier].name}<br>自动喜用参考：${esc(h.autoFavorable?.element||'待核对')}</p>${h.floors.map(f=>`<section><h3>${esc(f.name)}</h3><p>红线：${f.boundary?.length||0} 个拐角 · 北向相对图纸旋转 ${f.north}°<br>横向最长 ${esc(f.extents?.width||'未知')} 米 / 纵向最长 ${esc(f.extents?.height||'未知')} 米</p>${f.rooms.map(r=>`<p>${esc(r.name)}（${ROOMS[r.type]}）：${esc(r.measurements?.width||'未知')} × ${esc(r.measurements?.depth||'未知')} 米</p>`).join('')}<p>物件：${f.markers.map(m=>esc(MARKERS[m.type])+(m.locked?'（已锁定）':'')).join('、')||'未标'}</p>${f.dimensionReference?`<p>尺寸参考（待核实）：${esc(f.dimensionReference.url)}<br>${esc(f.dimensionReference.note)}</p>`:''}</section>`).join('')}`, '<button class="btn primary" data-close>返回核对</button>');},
 'marker-done':()=>{selection=null;render();},
 'room-done':()=>{const r=floor().rooms.find(r=>r.id===selection);if(!r)return;if(!r.name.trim()||!dimensionValid(r.measurements?.width)||!dimensionValid(r.measurements?.depth))throw Error('请填写功能区名称、有效米数或“未知”。');if(!regionWithin(r,floor().boundary))throw Error('功能区超出了边界红线，请先拖动或缩放区域。');selection=null;render();},
 'improve-all':async()=>{const h=active(),items=improvementPlan(h,h.improvementGoals||[]);h.improvementResult={revision:h.revision,goals:[...h.improvementGoals],items,createdAt:new Date().toISOString()};await persist(h);render();$('.improvement-results')?.scrollIntoView({behavior:'smooth',block:'start'});},
 'reference-dimensions':()=>{const h=draft,f=floor(),query=encodeURIComponent(`${h.housingCity||''} ${h.district||''} ${h.community||''} 户型图 site:lianjia.com OR site:ke.com OR site:anjuke.com`);modal('查找户型参考',`<p>相同小区不一定是相同楼栋和户型。平台图纸只作参考，未核对的尺寸保持“未知”。</p><a class="btn outline" href="https://www.bing.com/search?q=${query}" target="_blank" rel="noopener noreferrer">查找这个小区的户型 ↗</a>${field('参考页面链接',`<input id="reference-url" type="url" value="${esc(f.dimensionReference?.url||'')}" placeholder="https://…">`)}${field('对应楼栋 / 户型与说明',`<textarea id="reference-note" maxlength="300">${esc(f.dimensionReference?.note||'')}</textarea>`)}<p class="hint">这里只保存参考来源，不自动换算或覆盖已填尺寸。请回图中填写核对后的数值。</p>`,`<button class="btn ghost" data-close>返回</button><button class="btn primary" id="save-reference">保存来源</button>`);$('#save-reference').onclick=()=>{const raw=$('#reference-url').value.trim();try{const u=new URL(raw);if(!['http:','https:'].includes(u.protocol))throw Error();f.dimensionReference={url:u.href,note:$('#reference-note').value.trim(),status:'待核实'};touch();$('#modal').close();toast('已保存参考来源，尺寸仍需核对。');}catch{toast('请填写有效的 http 或 https 页面链接。');}};},
 'recognition-dialog':async()=>{const f=floor();if(!f.recognition)f.recognition=await recognizeImage(f.image);modal('自动识图 · 待核对轮廓',`<p>只提取封闭线稿候选，不自动判断房间用途。采用后请在图中核对名称与范围。</p><div class="recognition-options">${f.recognition.candidates.map((r,i)=>`<label class="check"><input type="checkbox" data-candidate="${i}">轮廓 ${i+1} · 图中左 ${Math.round(r.x*100)}% / 上 ${Math.round(r.y*100)}% ${regionWithin(r,f.boundary)?'':'（超出红线，不能采用）'}</label>`).join('')||'<p>没有可用封闭轮廓，请手动勾画。</p>'}</div>`,`<button class="btn ghost" data-close>返回</button><button class="btn primary" id="use-candidates">采用所选</button>`);$('#use-candidates').onclick=()=>{const indices=$$('[data-candidate]:checked').map(el=>+el.dataset.candidate);if(!indices.length){toast('请先选择轮廓。');return;}if(indices.some(i=>!regionWithin(f.recognition.candidates[i],f.boundary))){toast('所选轮廓超出红线，请手动勾画。');return;}for(const i of indices)f.rooms.push({...structuredClone(f.recognition.candidates[i]),id:uid(),name:'功能区 '+(f.rooms.length+1),type:'other',measurements:{width:'未知',depth:'未知'},locked:false});f.recognition.candidates=f.recognition.candidates.filter((_,i)=>!indices.includes(i));touch();$('#modal').close();render();};}
});

Object.assign(handlers,{
 'map-environment':async()=>{const h=draft,address=[h.housingCity,h.district,h.community].filter(Boolean).join(' '),caps=await serviceCapabilities();if(!caps.maps){modal('地图周边',`<p>地图导入服务尚未开通。当前可到高德查看这个地址。</p><a class="btn outline" href="https://uri.amap.com/search?keyword=${encodeURIComponent(address)}&city=${encodeURIComponent(h.housingCity||'')}&callnative=0" target="_blank" rel="noopener noreferrer">打开高德地图 ↗</a>`,'<button class="btn primary" data-close>返回</button>');return;}
 modal('查询住宅周边',`<p>将“${esc(address)}”发送给高德地图查询周边。不会发送出生资料或户型图。</p>`,'<button class="btn ghost" data-close>返回</button><button class="btn primary" id="confirm-map-query">同意并查询</button>');
 $('#confirm-map-query').onclick=async()=>{try{const data=await service('locations',{address,city:h.housingCity});modal('确认住宅所在位置',`<p>请选择对应的位置。小区中心点不等于具体楼栋。</p><div class="map-candidates">${data.candidates.map((x,i)=>`<button class="btn outline" data-map-index="${i}">${esc(x.name)} · ${esc(x.level)}</button>`).join('')||'<p>没有找到，请回去补充更完整的地址。</p>'}</div>`,'<button class="btn ghost" data-close>返回</button>');$$('[data-map-index]').forEach(el=>el.onclick=async()=>{try{h.environment=await service('surroundings',{location:data.candidates[+el.dataset.mapIndex].location});touch();$('#modal').close();render();toast('已导入周边地点，报告会列出方位与距离。');}catch(e){toast(e.message);}});}catch(e){toast(e.message);}};
 },
 'recognize-furniture':async()=>{const f=floor(),caps=await serviceCapabilities();if(!caps.vision&&f.furnitureRecognition?.status!=='review'){modal('识别底图家具','<p>家具识别服务尚未开通。先从图标栏添加已有家具，拖到原图对应位置。</p>','<button class="btn primary" data-close>返回标记</button>');return;}
 const show=()=>{modal('核对识别出的家具',`<p>核对后才会加入标记。取消错误项目，缺少的可手动补充。</p>${f.furnitureRecognition.objects.map((m,i)=>`<label class="check"><input type="checkbox" data-recognized="${i}" checked>${symbol(m.type)} ${esc(CATALOG[m.type].name)}</label>`).join('')||'<p>没有识别到可确认的家具，请手动添加。</p>'}`,'<button class="btn ghost" data-close>返回</button><button class="btn primary" id="accept-furniture">采用所选</button>');$('#accept-furniture').onclick=()=>{for(const el of $$('[data-recognized]:checked')){const m=f.furnitureRecognition.objects[+el.dataset.recognized];if(!insideRoom(m,{points:f.boundary}))continue;if(f.markers.some(x=>x.type===m.type&&Math.hypot(x.x-m.x,x.y-m.y)<.03))continue;f.markers.push({id:uid(),type:m.type,x:m.x,y:m.y,uiScale:clamp(Math.max(m.width,m.height)*8,.5,3),locked:!!CATALOG[m.type].fixed,origin:'image-recognition',reviewed:true});}selection=null;touch();$('#modal').close();render();};};
 if(f.furnitureRecognition?.status==='review'){show();return;}
 modal('识别户型图中的家具','<p>将这张户型图发送到已配置的视觉识别服务，仅提取家具种类和位置。住宅报告仍由固定规则生成。</p>','<button class="btn ghost" data-close>返回</button><button class="btn primary" id="start-furniture-recognition">同意并识别</button>');$('#start-furniture-recognition').onclick=async()=>{try{$('#start-furniture-recognition').disabled=true;f.furnitureRecognition=await service('furniture',{image:f.image});show();}catch(e){toast(e.message);$('#start-furniture-recognition')?.removeAttribute('disabled');}};
 }
});

window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
try{serviceStatus=await serviceCapabilities();houses=(await listHouses()).map(normalizeHouse);page=['archive','plans'].includes(location.hash.slice(1))?location.hash.slice(1):'home';render();}catch(e){render();toast(e.message);}
